import json, sys, re, urllib.request, math, os, subprocess, importlib

# ── Ensure plotting deps on first run ────────────────────────────────────
for pkg, imp in (("numpy", "numpy"), ("pandas", "pandas"), ("matplotlib", "matplotlib"), ("seaborn", "seaborn")):
    try:
        importlib.import_module(imp)
    except ImportError:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "--quiet", "--disable-pip-version-check", pkg])

import numpy as np
import pandas as pd
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import seaborn as sns

# ── Parse input ─────────────────────────────────────────────────────────────────
raw = sys.stdin.read()
try:
    data = json.loads(raw)
except Exception:
    data = {}

# Unwrap { input: <DiscussionOutput>, context: {...} } if that's the shape.
if isinstance(data, dict) and 'input' in data and isinstance(data.get('input'), dict):
    inner = data['input']
    if 'responses' in inner or 'transcript' in inner:
        data = inner

responses = []
if isinstance(data, dict) and isinstance(data.get('responses'), list):
    responses = data['responses']

sunk_items, opp_items = [], []
def extract(msg):
    items = []
    for line in msg.splitlines():
        m = re.match(r'^\s*[-*]\s+(.+)', line)
        if m:
            items.append(m.group(1).strip())
    return items

for r in responses:
    name = (r.get('agentName') or '').strip().lower()
    for it in extract(r.get('message') or ''):
        if 'sunk' in name: sunk_items.append(it)
        elif 'opportun' in name: opp_items.append(it)

# ── Embed via Ollama ───────────────────────────────────────────────────────
def embed(text):
    body = json.dumps({'model': 'nomic-embed-text', 'prompt': text}).encode()
    req = urllib.request.Request('http://localhost:11434/api/embeddings', data=body, headers={'Content-Type': 'application/json'})
    with urllib.request.urlopen(req, timeout=30) as r:
        return json.loads(r.read())['embedding']

def cosine(a, b):
    dot = sum(x*y for x, y in zip(a, b))
    na = math.sqrt(sum(x*x for x in a))
    nb = math.sqrt(sum(y*y for y in b))
    return dot/(na*nb) if na and nb else 0.0

THRESHOLD = 0.72
matrix = None
pairs = []

if sunk_items and opp_items:
    sv = [embed(s) for s in sunk_items]
    ov = [embed(o) for o in opp_items]
    matrix = np.zeros((len(sunk_items), len(opp_items)))
    for i in range(len(sunk_items)):
        for j in range(len(opp_items)):
            matrix[i, j] = cosine(sv[i], ov[j])

    # Greedy assignment: each sunk/opp item used in at most one pair.
    # Highest-similarity pairs win first.
    candidates = []
    for i in range(len(sunk_items)):
        for j in range(len(opp_items)):
            if matrix[i, j] >= THRESHOLD:
                candidates.append((float(matrix[i, j]), i, j))
    candidates.sort(reverse=True)
    used_s, used_o = set(), set()
    for sim, i, j in candidates:
        if i in used_s or j in used_o:
            continue
        used_s.add(i); used_o.add(j)
        pairs.append({'sunk': sunk_items[i], 'opp': opp_items[j],
                      'sunk_idx': i, 'opp_idx': j,
                      'similarity': round(sim, 3)})

# ── Output paths ─────────────────────────────────────────────────────────────────
run_id = os.environ.get('OC_RUN_ID', 'local')
out_dir = os.path.abspath(f'./ledger-{run_id}')
os.makedirs(out_dir, exist_ok=True)
heatmap_path = os.path.join(out_dir, 'heatmap.png')
html_path = os.path.join(out_dir, 'ledger.html')

# ── Render heatmap ─────────────────────────────────────────────────────────────
def short(s, maxlen=50):
    p = s.split(':', 1)[0].strip()
    return p if len(p) <= maxlen else p[:maxlen-1] + '…'

if matrix is not None and matrix.size > 0:
    sunk_lbl = [f'S{i+1} — {short(s)}' for i, s in enumerate(sunk_items)]
    opp_lbl = [f'O{j+1} — {short(o)}' for j, o in enumerate(opp_items)]
    df = pd.DataFrame(matrix, index=sunk_lbl, columns=opp_lbl)
    sns.set_theme(style='white')
    fig, ax = plt.subplots(figsize=(max(10, 1.1*len(opp_items)), max(6, 0.6*len(sunk_items))))
    cmap = sns.diverging_palette(20, 220, s=80, l=55, as_cmap=True)
    sns.heatmap(df, annot=True, fmt='.2f', cmap=cmap, center=THRESHOLD,
        vmin=0.45, vmax=0.85, linewidths=0.5, linecolor='white',
        cbar_kws={'label': 'cosine similarity'}, ax=ax, annot_kws={'size': 8})
    for p in pairs:
        ax.add_patch(plt.Rectangle((p['opp_idx'], p['sunk_idx']), 1, 1,
            fill=False, edgecolor='crimson', lw=3))
    ax.set_title(f"The Ledger — Run {run_id}\nRed-outlined cells are same-pattern pairs (cosine ≥ {THRESHOLD})", fontsize=12, pad=15)
    ax.set_xlabel('Opportunity Cost items'); ax.set_ylabel('Sunk Cost items')
    plt.xticks(rotation=40, ha='right', fontsize=9)
    plt.yticks(rotation=0, fontsize=9)
    plt.tight_layout()
    plt.savefig(heatmap_path, dpi=130, bbox_inches='tight')
    plt.close()

# ── Render HTML ──────────────────────────────────────────────────────────────
def esc(s): return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

paired_si = {p['sunk_idx'] for p in pairs}
paired_oi = {p['opp_idx'] for p in pairs}

def render_item(idx, text, prefix, paired):
    mark = '⚠' if idx in paired else '&nbsp;'
    cls = 'item paired' if idx in paired else 'item'
    s = text.split(':', 1)
    short_txt = esc(s[0].strip())
    full_txt = esc(s[1].strip()) if len(s) > 1 else ''
    full_html = f'<div class="full">{full_txt}</div>' if full_txt else ''
    return f'<li class="{cls}"><span class="marker">{mark}</span><span class="id">{prefix}{idx+1}</span><span class="short">{short_txt}</span>{full_html}</li>'

sunk_html = '\n'.join(render_item(i, s, 'S', paired_si) for i, s in enumerate(sunk_items))
opp_html = '\n'.join(render_item(j, o, 'O', paired_oi) for j, o in enumerate(opp_items))

pairs_html = ''
for p in sorted(pairs, key=lambda p: -p['similarity']):
    pairs_html += f'<div class="pair"><div class="pair-sim">cosine similarity: <b>{p["similarity"]:.3f}</b></div><div class="pair-sunk"><span class="tag">Sunk S{p["sunk_idx"]+1}</span> {esc(p["sunk"])}</div><div class="pair-opp"><span class="tag">Opp O{p["opp_idx"]+1}</span> {esc(p["opp"])}</div></div>'

if not pairs_html:
    pairs_html = '<p style="color: var(--muted)">No overlap detected above threshold. The two sides of your ledger are asymmetric — the facts do not mirror each other. That is itself an answer.</p>'

html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>The Ledger — run {run_id}</title>
<style>
:root {{ --bg:#0f1115; --panel:#181c24; --border:#2a2f3a; --text:#d8dde6; --muted:#8892a0; --accent:#ff5c57; --accent-soft:rgba(255,92,87,0.12); --pair-bg:#1e2330; }}
html,body {{ margin:0; padding:0; background:var(--bg); color:var(--text); font-family:-apple-system,"Inter","Segoe UI",sans-serif; line-height:1.55; }}
.wrap {{ max-width:1200px; margin:0 auto; padding:32px 24px 80px; }}
h1 {{ font-size:26px; margin:0 0 6px; }}
.subtitle {{ color:var(--muted); font-size:14px; margin-bottom:24px; }}
.how {{ background:var(--panel); border:1px solid var(--border); padding:18px 22px; border-radius:10px; margin:16px 0 28px; font-size:14px; }}
.how h3 {{ margin:0 0 10px; font-size:15px; color:var(--accent); }}
.how ol {{ margin:6px 0 0 20px; padding:0; }}
.how li {{ margin-bottom:6px; }}
.heatmap {{ background:white; padding:16px; border-radius:10px; margin:0 auto 36px; max-width:100%; box-shadow:0 4px 20px rgba(0,0,0,0.3); }}
.heatmap img {{ display:block; width:100%; }}
.two-col {{ display:grid; grid-template-columns:1fr 1fr; gap:20px; margin-bottom:36px; }}
@media (max-width:900px) {{ .two-col {{ grid-template-columns:1fr; }} }}
.col {{ background:var(--panel); border:1px solid var(--border); border-radius:10px; padding:18px 22px; }}
.col h2 {{ margin:0 0 14px; font-size:17px; }}
.col.sunk h2 {{ color:#ffb86b; }}
.col.opp h2 {{ color:#8be9fd; }}
ul.items {{ list-style:none; margin:0; padding:0; }}
li.item {{ padding:10px 0; border-bottom:1px dashed var(--border); display:grid; grid-template-columns:20px 40px 1fr; gap:8px; align-items:baseline; }}
li.item:last-child {{ border-bottom:0; }}
li.item.paired {{ background:var(--accent-soft); margin:2px -12px; padding:10px 12px; border-radius:6px; border-bottom:1px dashed transparent; }}
.marker {{ color:var(--accent); font-weight:700; }}
.id {{ color:var(--muted); font-size:12px; font-family:"JetBrains Mono",monospace; }}
.short {{ font-weight:600; }}
