.pairs h2 {{ color:var(--accent); font-size:18px; margin-bottom:14px; }}
.pair {{ background:var(--pair-bg); border:1px solid var(--border); border-left:4px solid var(--accent); border-radius:8px; padding:14px 18px; margin-bottom:14px; }}
