.pair-sunk, .pair-opp {{ margin:6px 0; font-size:14px; }}
.tag {{ display:inline-block; font-size:11px; font-weight:700; padding:2px 7px; border-radius:4px; margin-right:6px; background:rgba(255,255,255,0.05); color:var(--muted); font-family:"JetBrains Mono",monospace; }}
.legend {{ font-size:13px; color:var(--muted); background:var(--panel); border:1px solid var(--border); padding:14px 18px; border-radius:10px; margin-bottom:24px; }}
.legend b {{ color:var(--accent); }}
</style></head><body><div class="wrap">
<h1>The Ledger — run {run_id}</h1>
<div class="subtitle">Automatically generated. Each run uses fresh embeddings and greedy pair assignment (one sunk item + one opp item per pair).</div>
<div class="how"><h3>How to read this</h3><ol>
<li><b>Heatmap first (30s).</b> Rows are sunk-cost items. Columns are opportunity-cost items. Cells with a red border are "same underlying pattern, stated from two directions."</li>
<li><b>Highlighted rows (2 min).</b> Items marked ⚠ appeared in a flagged pair — read those first.</li>
<li><b>Pair cards (5 min, slowly).</b> Each card is a single pattern, stated once as what you\'re protecting and once as what\'s being foreclosed. Read each one as a loop. That\'s the insight.</li>
</ol></div>
<div class="legend"><b>Threshold: {THRESHOLD}</b> — items that cross this line are flagged as the same underlying concept. Greedy assignment means each item appears in at most one pair.</div>
<div class="heatmap"><img src="heatmap.png" alt="Similarity heatmap"></div>
<div class="two-col"><div class="col sunk"><h2>Sunk Cost</h2><ul class="items">{sunk_html}</ul></div><div class="col opp"><h2>Opportunity Cost</h2><ul class="items">{opp_html}</ul></div></div>
<div class="pairs"><h2>⚠ Patterns appearing on both sides</h2>{pairs_html}</div>
</div></body></html>'''

with open(html_path, 'w', encoding='utf-8') as f:
    f.write(html)

# ── Plain text ledger (for channel/Telegram) ─────────────────────────────────────
lines = [f'# The Ledger — run {run_id}', '']
if html_path:
    lines.append(f'→ Open in browser: {html_path}')
    lines.append('')
lines.append('## SUNK COST')
for i, s in enumerate(sunk_items):
    m = '⚠ ' if i in paired_si else '  '
    lines.append(f'{m}S{i+1} — {s}')
lines.append('')
lines.append('## OPPORTUNITY COST')
for j, o in enumerate(opp_items):
    m = '⚠ ' if j in paired_oi else '  '
    lines.append(f'{m}O{j+1} — {o}')
if pairs:
    lines.append('')
    lines.append('## ⚠ PATTERNS APPEARING ON BOTH SIDES (greedy-deduped)')
    for p in pairs:
        lines.append('')
        lines.append(f"**S{p['sunk_idx']+1}:** {p['sunk']}")
        lines.append(f"**O{p['opp_idx']+1}:** {p['opp']}")
        lines.append(f"_similarity: {p['similarity']}_")
else:
    lines.append('')
    lines.append('_No overlap detected. The two sides are asymmetric — the facts do not mirror each other._')

result = {
    'ledger': '\n'.join(lines),
    'pairs': [{'sunk': p['sunk'], 'opp': p['opp'], 'similarity': p['similarity']} for p in pairs],
    'sunk_count': len(sunk_items),
    'opp_count': len(opp_items),
    'html_path': html_path,
    'heatmap_path': heatmap_path,
}
print(json.dumps(result))
